    help: (port: number) => `agent-office tunnel — 모든 직원의 웹 서버를 이 컴퓨터에서 자동으로 엽니다

사용법:
  agent-office tunnel [where] [options] [-- <ssh options>]

내 컴퓨터에서 실행하고 계속 켜 두세요. 사무실의 직원이 웹 서버(npm run dev,
미리보기 빌드 등)를 시작할 때마다 같은 포트가 여기에서 열립니다. 이 컴퓨터의
http://localhost:5173은 직원의 localhost:5173입니다. 직원이 서버를 중지하면 다시
닫힙니다. 서버마다 명령을 실행하거나 다시 시작할 필요가 없습니다.

사무실 위치:
  office@203.0.113.7      SSH 주소(👥 팀원 초대에 표시되는 주소, ssh:// 형식이나
  ssh://office@host:2222  ssh config의 Host도 가능). 사무실로 가는 터널도 함께
                          열고, 브라우저에서 사무실을 열며, 연결이 끊기면
                          터널을 다시 엽니다
  http://localhost:4600   브라우저에서 이미 열 수 있는 사무실: 실행 중인 터널,
  https://office.example  도메인 또는 tailnet을 통해 접속합니다.
                          기본값은 http://localhost:4600

브라우저와 같은 방식으로 로그인합니다. 처음에는 사무실 비밀번호(또는 내 이름과
개인 비밀번호)를 묻고, 다음을 위해 세션을 저장합니다.

옵션:
  -p, --port <n>          SSH 주소 사용 시: 이 컴퓨터에서 사무실에 쓸 포트
                          (기본값: --office-port와 같음)
      --office-port <n>   SSH 주소 사용 시: 사무실 컴퓨터에서의 사무실 포트
                          (기본값 ${port})
      --name <name>       이 계정으로 로그인 (env AGENT_OFFICE_NAME)
      --password <pw>     묻는 대신 사용할 비밀번호
                          (env AGENT_OFFICE_PASSWORD)
      --no-open           SSH 주소 사용 시: 브라우저에서 사무실을 열지 않음
      --insecure          신뢰할 수 없는 인증서 허용 (--self-signed)
  -h, --help              이 도움말 표시

-- 뒤의 모든 내용은 ssh에 전달됩니다. 예:  agent-office tunnel office@host -- -i ~/.ssh/office
`,
    needsPort: (flag: string) => `${flag}에는 포트 번호가 필요합니다`,
